def taller_within(a: list[int], k: int) -> list[int]:
    if k == 0:
        return [0] * len(a)

    ranks = {value: i + 1 for i, value in enumerate(sorted(set(a)))}
    tree = [0] * (len(ranks) + 1)
    result = []

    for i, height in enumerate(a):
        if i > k:
            rank = ranks[a[i - k - 1]]
            while rank < len(tree):
                tree[rank] -= 1
                rank += rank & -rank

        rank = ranks[height]
        count_not_taller = 0
        index = rank
        while index:
            count_not_taller += tree[index]
            index -= index & -index

        result.append(min(i, k) - count_not_taller)

        while rank < len(tree):
            tree[rank] += 1
            rank += rank & -rank

    return result
